use strict;
use warnings;
use ExtUtils::MakeMaker;

WriteMakefile(
    NAME             => 'Text::Wrap::Smart',
    VERSION_FROM     => 'lib/Text/Wrap/Smart.pm',
    MIN_PERL_VERSION => '5.008001',
    PREREQ_PM        => { 'URI' => '1.60' },
    TEST_REQUIRES    => { 'Test::More' => '0.88' },
);

package Text::Wrap::Smart;
use strict;
use warnings;
use URI;

our $VERSION = '0.01';

sub host {
    my ($class, $url) = @_;
    return URI->new($url)->host;
}

1;

use strict;
use warnings;
use Test::More;
use Text::Wrap::Smart;

is(Text::Wrap::Smart->host('https://example.org/x'), 'example.org', 'reads host');

done_testing();
